#include <vector>
#include <cmath>
#define main hecbench_original_main
#include "chacha20-cuda/main.cu"
#undef main
void emit(int trial,double seconds,const std::vector<double>&result,const std::vector<double>&expected,int repeat,double atol=0.,double rtol=0.){
 double error=0;bool correct=result.size()==expected.size();for(size_t i=0;i<result.size();i++){double e=fabs(result[i]-expected[i]);error=fmax(error,e);correct &= std::isfinite(result[i])&&e<=atol+rtol*fabs(expected[i]);}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(result.data(),8,result.size(),f);fclose(f);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"timing_region\":\"synchronized_kernel_loop_mean\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,correct?"true":"false",result.size(),error,repeat,path,result.size());if(!correct)exit(1);
}
const char*KEY="000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f";const char*NONCE="0001020304050607";const char*STREAM="";
int nibble(char c){return c<='9'?c-'0':c-'a'+10;}std::vector<uint8_t>decode(const char*s){std::vector<uint8_t>v(strlen(s)/2);for(size_t i=0;i<v.size();i++)v[i]=(nibble(s[2*i])<<4)|nibble(s[2*i+1]);return v;}
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):10,nbytes=strlen(STREAM)/2;std::vector<uint8_t>table(256,0);for(int i=0;i<10;i++)table[i+'0']=i;for(int i=0;i<26;i++)table[i+'a']=table[i+'A']=i+10;std::vector<double>expected;for(auto v:decode(STREAM))expected.push_back(v);for(auto v:decode(KEY))expected.push_back(v);for(auto v:decode(NONCE))expected.push_back(v);for(auto v:decode(STREAM))expected.push_back(v);char *tk,*tn,*tr;uint8_t *lut,*rk,*rn,*rr,*out;cudaMalloc(&tk,strlen(KEY));cudaMalloc(&tn,strlen(NONCE));cudaMalloc(&tr,strlen(STREAM));cudaMemcpy(tk,KEY,strlen(KEY),cudaMemcpyHostToDevice);cudaMemcpy(tn,NONCE,strlen(NONCE),cudaMemcpyHostToDevice);cudaMemcpy(tr,STREAM,strlen(STREAM),cudaMemcpyHostToDevice);cudaMalloc(&lut,256);cudaMemcpy(lut,table.data(),256,cudaMemcpyHostToDevice);cudaMalloc(&rk,32);cudaMalloc(&rn,8);cudaMalloc(&rr,nbytes);cudaMalloc(&out,nbytes);auto launch=[&](){cudaMemset(out,0,nbytes);test_keystreams<<<1,256>>>(tk,tn,tr,lut,rk,rn,rr,out,strlen(KEY),strlen(NONCE),strlen(STREAM));};launch();cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){auto start=std::chrono::steady_clock::now();for(int j=0;j<repeat;j++)launch();cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;std::vector<double>values;for(auto spec:std::vector<std::pair<uint8_t*,int>>{{out,nbytes},{rk,32},{rn,8},{rr,nbytes}}){std::vector<uint8_t>v(spec.second);cudaMemcpy(v.data(),spec.first,v.size(),cudaMemcpyDeviceToHost);for(auto x:v)values.push_back(x);}emit(trial,seconds,values,expected,repeat);}cudaFree(tk);cudaFree(tn);cudaFree(tr);cudaFree(lut);cudaFree(rk);cudaFree(rn);cudaFree(rr);cudaFree(out);return 0;}
